#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
layout(color) uniform half4 amzp_color1;
uniform float amzp_AMOUNT;
uniform float2 amzp_position;
uniform float amzp_progressa;
uniform float amzp_scalex;
uniform float amzp_bright;
uniform float amzp_alpha;
uniform float amzp_angle;
uniform float amzp_blendMode;
    float2x2 rot2m(float a){
 float s = sin(a);
 float c = cos(a);
 return float2x2(c, -s, s, c);
    }
    float2 l2s( float2 v ) {
        return (float4(v,0.,1.)*amzLayerToScreen()).xy;
    }
      const float overallSpeed = 0.2;
      const float gridSmoothWidth = 0.015;
      const float axisWidth = 0.05;
      const float majorLineWidth = 0.025;
      const float minorLineWidth = 0.0125;
      const float majorLineFrequency = 5.0;
      const float minorLineFrequency = 1.0;
      const float4 gridColor = float4(0.5);
      const float scale = 5.0;
      const float minLineWidth = 0.02;
      const float maxLineWidth = 0.5;
      const float lineSpeed = 1.0 * overallSpeed;
      const float lineAmplitude = 1.0;
      const float lineFrequency = 0.2;
      const float warpSpeed = 0.2 * overallSpeed;
      const float warpFrequency = 0.5;
      const float warpAmplitude = 1.0;
      const float offsetFrequency = 0.5;
      const float offsetSpeed = 1.33 * overallSpeed;
      const float minOffsetSpread = 0.6;
      const float maxOffsetSpread = 2.0;
      float drawGridLines(float axis)
      {
          return smoothstep(axisWidth + gridSmoothWidth, axisWidth, abs(0.0 - (axis)))
                 + smoothstep(majorLineWidth + gridSmoothWidth, majorLineWidth, abs(majorLineFrequency / 2.0 - (abs(mod(axis, majorLineFrequency) - (majorLineFrequency) / 2.0))))
                 + smoothstep(minorLineWidth + gridSmoothWidth, minorLineWidth, abs(minorLineFrequency / 2.0 - (abs(mod(axis, minorLineFrequency) - (minorLineFrequency) / 2.0))));
      }
      float drawGrid(float2 space)
      {
          return min(1., drawGridLines(space.x)
                        +drawGridLines(space.y));
      }
      float random(float t)
      {
          return (cos(t) + cos(t * 1.3 + 1.3) + cos(t * 1.4 + 1.4)) / 3.0;
      }
      float getPlasmaY(float x, float horizontalFade, float offset)
      {
          return random(x * lineFrequency + amzp_progressa * lineSpeed) * horizontalFade * lineAmplitude + offset;
      }
    void amzRender()
    {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 satriyaid;
        satriyaid = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        satriyaid.y*=layer.y/layer.x;
        satriyaid /= amzp_scalex;
        satriyaid *= rot2m((-175.0+amzp_angle)*0.0174533);
        satriyaid += float2((0.0+amzp_position.x), (0.0+amzp_position.y))*float2(-1.,1.)/500.;
     float4 fragColor;
          float2 uv = amzScreenNorm();
          float2 space = satriyaid;
          float horizontalFade = 1.0 - (cos(uv.x * 6.28) * 0.5 + 0.5);
          float verticalFade = 1.0 - (cos(uv.y * 6.28) * 0.5 + 0.5);
          space.y += random(space.x * warpFrequency + amzp_progressa * warpSpeed) * warpAmplitude * (0.5 + horizontalFade);
          space.x += random(space.y * warpFrequency + amzp_progressa * warpSpeed + 2.0) * warpAmplitude * horizontalFade;
          float4 lines = float4(0);
          for(float l = 0.0; l < amzp_AMOUNT; l++)
          {
              float normalizedLineIndex = float(l) / float(amzp_AMOUNT);
              float offsetTime = amzp_progressa * offsetSpeed;
              float offsetPosition = float(l) + space.x * offsetFrequency;
              float rand = random(offsetPosition + offsetTime) * 0.5 + 0.5;
              float halfWidth = mix(minLineWidth, maxLineWidth, rand * horizontalFade) / 2.0;
              float offset = random(offsetPosition + offsetTime * (1.0 + normalizedLineIndex)) * mix(minOffsetSpread, maxOffsetSpread, horizontalFade);
              float linePosition = getPlasmaY(space.x, horizontalFade, offset);
              float line = smoothstep(halfWidth, 0.0, abs(linePosition - (space.y))) / 2.0 + smoothstep(halfWidth * 0.15 + gridSmoothWidth, halfWidth * 0.15, abs(linePosition - (space.y)));
              float circleX = mod(float(l) + amzp_progressa * lineSpeed, 25.0) - 12.0;
              float2 circlePosition = float2(circleX, getPlasmaY(circleX, horizontalFade, offset));
              float circle = smoothstep(0.01 + gridSmoothWidth, 0.01, length(space - (circlePosition))) * 4.0;
              line = line + circle;
              lines += line * float4(amzp_color1.rgb, 1.0) * rand;
          }
          fragColor = float4(0.,0.,0.,1.);
          fragColor *= verticalFade;
          fragColor.a = 1.0;
          fragColor += lines;
     float4 factor = mix(texColorX,fragColor,amzp_alpha);
        float4 resultfinal;
        if( int(amzp_blendMode)==0 ) {
            resultfinal = (factor * amzp_bright) * texColor.a;
        } else if( int(amzp_blendMode)==1 ) {
            factor *= amzp_bright;
            float4 c = factor + float4(1.)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( int(amzp_blendMode)==2 ) {
            factor *= amzp_bright;
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }
     amzOutput = resultfinal;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
